import java.util.concurrent.*;

public class Main {
    static class Somma extends RecursiveTask<Long> {
        final int da, a;
        Somma(int da, int a) { this.da = da; this.a = a; }
        protected Long compute() {
            if (a - da <= 1000) {
                long s = 0;
                for (int i = da; i < a; i++) s += i;
                return s;
            }
            int m = (da + a) / 2;
            Somma sx = new Somma(da, m);
            sx.fork();
            return new Somma(m, a).compute() + sx.join();
        }
    }
    public static void main(String[] args) {
        System.out.println(new ForkJoinPool().invoke(new Somma(0, 100_000)));
    }
}

